\choice
{ $x<10$ }
   { $x\le 10$ }
     { \True $x >10$ }
    { $x \ge 10$ }
\loigiai{
Giải bất phương trình bậc nhất một ẩn bằng cách chuyển vế hằng số rồi chia hai vế cho hệ số $1$: $1x > 10 \Leftrightarrow x > 10$.
}\end{ex}

\begin{ex}%[9D2H3-2]
Nghiệm của bất phương trình $7 - 8 x >0$ là:
\choice
{ $x \ge \dfrac{7}{8}$ }
   { $x\le \dfrac{7}{8}$ }
     { $x>\dfrac{7}{8}$ }
    { \True $x <\dfrac{7}{8}$ }
\loigiai{
Giải bất phương trình bậc nhất một ẩn bằng cách chuyển vế hằng số rồi chia hai vế cho hệ số $-8$ (chia hai vế cho số âm nên đổi chiều bất đẳng thức): $-8x > -7 \Leftrightarrow x < \dfrac{7}{8}$.
}\end{ex}

\begin{ex}%[9D2H3-2]
Nghiệm của bất phương trình $4 x + 4 >0$ là:
\choice
{ $x<-1$ }
   { $x\le -1$ }
     { \True $x >-1$ }
    { $x \ge -1$ }
\loigiai{
Giải bất phương trình bậc nhất một ẩn bằng cách chuyển vế hằng số rồi chia hai vế cho hệ số $4$: $4x > -4 \Leftrightarrow x > -1$.
}\end{ex}

\begin{ex}%[9D2H3-2]
Nghiệm của bất phương trình $7 - 5 x >0$ là:
\choice
{ $x>\dfrac{7}{5}$ }
   { \True $x <\dfrac{7}{5}$ }
     { $x\le \dfrac{7}{5}$ }
    { $x \ge \dfrac{7}{5}$ }
\loigiai{
Giải bất phương trình bậc nhất một ẩn bằng cách chuyển vế hằng số rồi chia hai vế cho hệ số $-5$ (chia hai vế cho số âm nên đổi chiều bất đẳng thức): $-5x > -7 \Leftrightarrow x < \dfrac{7}{5}$.
}\end{ex}
